u0437-\u0437\u0430 \u043f\u043e\u0441\u0442\u0440\u043e\u0447\u043d\u043e\u0439 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b `o_proj`. \u0426\u0435\u043d\u0430: \u0440\u0430\u043d\u0442\u0430\u0439\u043c-FLOPs \u043d\u0430 \u043a\u0430\u0436\u0434\u044b\u0439 \u0442\u043e\u043a\u0435\u043d, **\u0431\u0435\u0437** \u0442\u043e\u0433\u043e \u0431\u043e\u043d\u0443\u0441\u0430, \u043a\u043e\u0442\u043e\u0440\u044b\u0439 \u043e\u043d\u0438 \u0434\u0430\u044e\u0442 \u0432 W4A4 (\u0442\u0430\u043c \u043e\u043d\u0438 \u0443\u0431\u0438\u0440\u0430\u044e\u0442 outlier-\u0430\u043a\u0442\u0438\u0432\u0430\u0446\u0438\u0438 \u0438\u0437 \u043a\u0432\u0430\u043d\u0442\u0438\u0437\u0430\u0442\u043e\u0440\u0430). \u0412 W-only \u0438\u0445 \u043f\u043e\u043b\u0435\u0437\u043d\u043e\u0441\u0442\u044c \u2014 \u0447\u0438\u0441\u0442\u044b\u0439 \u0432\u043e\u043f\u0440\u043e\u0441 \u00ab\u043e\u043f\u0440\u0430\u0432\u0434\u0430\u043d \u043b\u0438 \u043f\u043b\u0430\u0442\u043d\u044b\u0439 rotation \u0434\u043b\u044f \u0432\u0435\u0441\u043e\u0432\u043e\u0433\u043e \u0448\u0443\u043c\u0430\u00bb.\n\n\u0421\u043b\u0435\u0434\u0441\u0442\u0432\u0438\u0435 \u0434\u043b\u044f \u0432\u044b\u0432\u043e\u0434\u0430: \u00abQuaRot \u0443\u043b\u0443\u0447\u0448\u0430\u0435\u0442 weight-only\u00bb \u2260 \u043c\u043e\u043d\u043e\u043b\u0438\u0442; \u043e\u043d \u0440\u0430\u0441\u043a\u043b\u0430\u0434\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u043d\u0430 \u0394(A1\u2192A2) [\u0438\u043d\u0432\u0430\u0440\u0438\u0430\u043d\u0442\u043d\u043e\u0441\u0442\u044c \u043f\u0440\u043e\u0442\u0438\u0432 \u043f\u0440\u043e\u0441\u0442\u043e\u0433\u043e \u0441\u043c\u0435\u043d\u0430 \u0431\u0430\u0437\u0438\u0441\u0430] \u0438 \u0394(A2\u2192A3) [\u0434\u043e\u043b\u044f, \u043a\u0443\u043f\u043b\u0435\u043d\u043d\u0430\u044f \u0440\u0430\u043d\u0442\u0430\u0439\u043c\u043e\u043c].\n\n**1.2 \u041c\u0435\u0445\u0430\u043d\u0438\u0437\u043c-\u0433\u0438\u043f\u043e\u0442\u0435\u0437\u0430.** Hadamard \u043f\u0435\u0440\u0435\u0440\u0430\u0441\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442 \u00ab\u0442\u043e\u043b\u0441\u0442\u044b\u0435 \u0445\u0432\u043e\u0441\u0442\u044b\u00bb \u043f\u043e \u043a\u0430\u043d\u0430\u043b\u0430\u043c \u2192 per-group \u0448\u043a\u0430\u043b\u0430 \u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u0441\u044f \u0431\u043b\u0438\u0436\u0435 \u043a \u0440\u0430\u0432\u043d\u043e\u043c\u0435\u0440\u043d\u043e\u0439 \u2192 MSE \u043a\u0432\u0430\u043d\u0442\u0438\u0437\u0430\u0446\u0438\u0438 \u043f\u0430\u0434\u0430\u0435\u0442 \u2192 PPL/accuracy \u0432\u044b\u0448\u0435 \u043d\u0430 \u043d\u0438\u0437\u043a\u0438\u0445 \u0431\u0438\u0442\u0430\u0445. \u041f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u043a\u043e\u043d\u0435\u0447\u043d\u043e\u0439 \u043c\u0435\u0442\u0440\u0438\u043a\u043e\u0439, \u0430 \u0446\u0435\u043f\u043e\u0447\u043a\u043e\u0439 outlier \u2192 MSE \u2192 PPL (\u00a76).\n\n## 2. \u0421\u0435\u0442\u043a\u0430 \u0443\u0441\u043b\u043e\u0432\u0438\u0439\n\n**\u041c\u043e\u0434\u0435\u043b\u0438 [A]:** core = LLaMA-3-8B, OPT-1.3B; full = + Mistral-7B-v0.1, LLaMA-2-13B, Pythia-2.8B; 70B \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0432 \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u043c T2-stretch **[O]**.\n\n| \u0411\u043b\u043e\u043a | \u0423\u0441\u043b\u043e\u0432\u0438\u0435 | \u0420\u043e\u0442\u0430\u0446\u0438\u044f (\u0432\u0430\u0440\u0438\u0430\u043d\u0442) | Backend | W | g | Seed \u0440\u043e\u0442\u0430\u0446\u0438\u0438 | \u0412 \u0441\u0435\u0442\u043a\u0435 |\n|---|---|---|---|---|---|---|---|\n| Ref | FP16 | \u2014 | \u2014 | 16 | \u2014 | \u2014 | \u0432\u0441\u0435 \u043c\u043e\u0434\u0435\u043b\u0438 |\n| Base | RTN | A0 identity | RTN | 4,3,2 | 128 | n/a | core+full |\n| Base | GPTQ | A0 identity | GPTQ | 4,3,2 | 128 | 1 (damping 0.01 **[A]**) | core+full |\n| **Main** | QuaRot+RTN | **A3 full** | RTN | 4,3,2 | 128 | 3 | core+full |\n| **Main** | QuaRot+GPTQ | **A3 full** | GPTQ | 4,3,2 | 128 | 3 | core+full |\n\n**Ablation A \u2014 \u0440\u0430\u0437\u043c\u0435\u0449\u0435\u043d\u0438\u0435/\u043e\u043d\u043b\u0430\u0439\u043d\u043e\u0432\u043e\u0441\u0442\u044c \u0432\u0440\u0430\u0449\u0435\u043d\u0438\u044f** (backend=GPTQ, W\u2208{3,2} **[S \u0434\u043b\u044f \u043d\u0430\u0431\u043e\u0440\u0430 \u0431\u0438\u0442]**, +A3\u00b7RTN \u043f\u0440\u0438 W2 \u043a\u0430\u043a \u0434\u0435\u0448\u0451\u0432\u044b\u0439 \u043a\u0440\u043e\u0441\u0441-\u0447\u0435\u043a):\n\n| ID | \u0427\u0442\u043e \u0432\u043a\u043b\u044e\u0447\u0435\u043d\u043e | \u0418\u043d\u0432\u0430\u0440\u0438\u0430\u043d\u0442\u043d\u043e\u0441\u0442\u044c | \u0418\u043d\u0444\u0435\u0440\u0435\u043d\u0441-\u0446\u0435\u043d\u0430 | \u0427\u0442\u043e \u0438\u0437\u043e\u043b\u0438\u0440\u0443\u0435\u0442 |\n|---|---|---|---|---|\n| A0 | \u043d\u0438\u0447\u0435\u0433\u043e (=baseline) | \u0442\u0440\u0438\u0432\u0438\u0430\u043b\u044c\u043d\u0430\u044f | 0 |reference |\n| A1 | \u0432\u0435\u0441\u043e\u0432\u043e\u0439 \u0441\u043c\u0435\u043d\u0430-\u0431\u0430\u0437\u0438\u0441 per-layer (rotate-quantize-rotate-back), \u0431\u0435\u0437 \u043f\u0430\u0440\u043d\u044b\u0445 \u0430\u043a\u0442\u0438\u0432\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0445 \u0432\u0440\u0430\u0449\u0435\u043d\u0438\u0439 | **\u043d\u0435\u0442** (\u043f\u0435\u0440\u0442\u0443\u0440\u0431\u0430\u0446\u0438\u044f \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044f \u043d\u0430\u0437\u0430\u0434) | 0 | \u00ab\u0431\u0435\u0441\u043f\u043b\u0430\u0442\u043d\u0430\u044f\u00bb \u0432\u0435\u0441\u043e\u0432\u0430\u044f \u0447\u0430\u0441\u0442\u044c Hadamard |\n| A2 | \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u0435\u043c\u044b\u0435 invariance-\u043f\u0430\u0440\u044b (global hidden + \u043f\u0430\u0440\u0430 V/o_proj), \u043a\u